#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 10;
template <int maxn>
int solve(int n, int k) {
    if (maxn <= n) {
        return solve<min(N, maxn * 2)>(n, k);
    }
    bitset<maxn> dp;
    vector<int> fa(n, -1), dep(n, 0);
    vector<int> noson(n, 1), cnt(n + 1);
    cnt[0]++;
    for (int i = 1; i < n; i++) {
        cin >> fa[i], fa[i]--;
        dep[i] = dep[fa[i]] + 1;
        cnt[dep[i]]++;
        noson[fa[i]] = 0;
    }
    dp.reset();
    dp[0] = 1;
    int mxdep = 1e9;
    for (int i = 0; i < n; i++)
        if (noson[i]) mxdep = min(mxdep, dep[i]);

    int sum = 0;
    vector<int> all(cnt.begin(), cnt.begin() + mxdep + 1);
    sort(all.begin(), all.end());
    vector<int> v;
    for (int i = 0; i < (int)all.size(); i++) {
        int j = i;
        while (j + 1 < (int)all.size() && all[i] == all[j + 1]) j++;
        int t = j - i + 1;
        for (int z = 1; z <= t; z *= 2) {
            v.push_back(z * all[i]);
            t -= z;
        }
        if (t > 0) v.push_back(t * all[i]);
        i = j;
    }
    dp[0] = 1;
    for (auto val : v) {
        sum += val;
        dp |= (dp << val);
    }
    if (sum <= k || sum <= n - k) return mxdep + 1;
    for (int i = 0; i <= sum; i++)
        if (dp[i]) {
            if (i <= k && sum - i <= n - k) return mxdep + 1;
        }
    return mxdep;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int T;
    cin >> T;
    while (T--) {
        int n, k;
        cin >> n >> k;
        cout << solve<1>(n, k) << "\n";
    }
    return 0;
}

